import{_ as t,I as a,g as o,j as i}from"./chunks/framework.CjoWWfVe.js";const d=JSON.parse('{"title":"Raw Materials (Materials Stock)","description":"How batch inventory accounting, logistics, and MAC (Moving Average Cost) work in OmniCraft ERP.","frontmatter":{"title":"Raw Materials (Materials Stock)","description":"How batch inventory accounting, logistics, and MAC (Moving Average Cost) work in OmniCraft ERP.","order":5},"headers":[],"relativePath":"docs/spaces/production/warehouse.md","filePath":"docs/spaces/production/warehouse.md"}'),r={name:"docs/spaces/production/warehouse.md"};function s(n,e,c,l,h,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="📦-raw-materials-materials-stock-batch-purchases" tabindex="-1">📦 Raw Materials: Materials Stock &amp; Batch Purchases <a class="header-anchor" href="#📦-raw-materials-materials-stock-batch-purchases" aria-label="Permalink to &quot;📦 Raw Materials: Materials Stock &amp; Batch Purchases&quot;">​</a></h1><p>The <strong>&quot;Materials&quot;</strong> tab is the logistical heart of your craft business. Here, you store all materials physically used in production: leather, thread, glue, hardware, fabric, wood, and packaging.</p><p>OmniCraft ERP utilizes a professional cost-accounting method: <strong>MAC (Moving Average Cost)</strong>, saving you from manually calculating how much a square foot of leather costs after factoring in shipping.</p><hr><h2 id="📋-material-profile" tabindex="-1">📋 Material Profile <a class="header-anchor" href="#📋-material-profile" aria-label="Permalink to &quot;📋 Material Profile&quot;">​</a></h2><p>Before purchasing a material, you need to add it to your inventory database. Click the <strong>&quot;+&quot; (New Material)</strong> button on the top toolbar.</p><p>In the material profile, you specify:</p><ul><li><strong>Name:</strong> For example, <em>“Buttero Leather (Cognac)”</em>.</li><li><strong>Category:</strong> Grouping for organization (e.g., <em>“Genuine Leather”</em>, <em>“Thread”</em>, <em>“Hardware”</em>). Categories can be edited on the fly by clicking the pencil icon.</li><li><strong>Units of Measurement:</strong> What unit you will use to measure the material in your recipes (sq ft, pcs, ml, yards). <em>Important: Choose the unit that is most convenient for calculating consumption per single item.</em></li></ul><blockquote><p><strong>Linking Suppliers and Product Pages</strong> If you click the pencil icon ✏️ next to an existing material, its detailed profile will open. There, you can bind specific suppliers (e.g., <em>“Conceria Walpier”</em>, <em>“Local Leather Distributor”</em>) and save direct web links to the items, allowing you to reorder them in a single click in the future.</p></blockquote><hr><h2 id="🛒-batch-purchases-logistics" tabindex="-1">🛒 Batch Purchases &amp; Logistics <a class="header-anchor" href="#🛒-batch-purchases-logistics" aria-label="Permalink to &quot;🛒 Batch Purchases &amp; Logistics&quot;">​</a></h2><p>The primary &quot;magic&quot; of OmniCraft ERP lies within the <strong>&quot;Batch Purchase&quot;</strong> button (the shopping cart icon in the top menu). Never enter purchased materials via inventory adjustments—always use batch purchases!</p><h3 id="how-smart-shipping-allocation-works" tabindex="-1">How smart shipping allocation works: <a class="header-anchor" href="#how-smart-shipping-allocation-works" aria-label="Permalink to &quot;How smart shipping allocation works:&quot;">​</a></h3><p>Suppose you ordered from a supplier:</p><ol><li>A piece of leather for <code>$100</code></li><li>A set of buckles for <code>$20</code></li><li>And paid a shipping fee of <code>$12</code>.</li></ol><p>If you simply split the <code>$12</code> shipping fee in half (<code>$6</code> per item), the cost price of the cheap buckles would skyrocket, heavily distorting the cost price of your finished products.</p><p><strong>OmniCraft ERP allocates shipping proportionally to the value of the items:</strong></p><ul><li>The leather (<code>$100</code>) absorbs <code>$10</code> of the shipping cost.</li><li>The buckles (<code>$20</code>) absorb only <code>$2</code> of the shipping cost. The software performs this calculation in a fraction of a second, logging a fair and balanced cost price for each item in your warehouse.</li></ul><h3 id="what-happens-when-you-process-a-purchase" tabindex="-1">What happens when you process a purchase: <a class="header-anchor" href="#what-happens-when-you-process-a-purchase" aria-label="Permalink to &quot;What happens when you process a purchase:&quot;">​</a></h3><ol><li>The physical quantity of materials is added to your stock.</li><li>The program recalculates the <strong>MAC price</strong>. If you had remaining leather at an older price and purchased a new piece at a higher price, the software automatically averages their cost.</li><li>In your <strong>Cash Flow</strong> ledger, two expense entries are automatically created: <em>“Purchase of Raw Materials”</em> (for <code>$120</code>) and <em>“Logistics”</em> (for <code>$12</code>).</li></ol><hr><h2 id="⚖️-inventory-adjustment-stock-correction" tabindex="-1">⚖️ Inventory Adjustment (Stock Correction) <a class="header-anchor" href="#⚖️-inventory-adjustment-stock-correction" aria-label="Permalink to &quot;⚖️ Inventory Adjustment (Stock Correction)&quot;">​</a></h2><p>The <strong>&quot;Inventory Adjustment&quot;</strong> button (the scale icon) is used <strong>only</strong> to correct physical discrepancies in your warehouse.</p><p>For example, if the software shows you have 15 sq ft of leather left, but physically you only have small scraps that cannot be crafted into anything, you perform an inventory adjustment and write off the deficit.</p><ul><li><strong>Financial Safety:</strong> Inventory adjustments <strong>do not</strong> touch your Cash Flow ledger or Balance Sheet. They only adjust physical quantities, preventing the program from letting you schedule production with non-existent materials.</li></ul><hr><h2 id="🗄️-archiving-deletion" tabindex="-1">🗄️ Archiving &amp; Deletion <a class="header-anchor" href="#🗄️-archiving-deletion" aria-label="Permalink to &quot;🗄️ Archiving &amp; Deletion&quot;">​</a></h2><p>If you stop working with a specific material (for example, a supplier discontinues a certain edge paint), you can send it to the <strong>Archive</strong> (the red box icon).</p><ul><li>The material will disappear from your active list, keeping search results clean.</li><li>When moving an item to the archive, the program will suggest <strong>zeroing out remaining stock</strong> if there is any left.</li><li>An archived material can be restored at any time by switching to the &quot;Archived&quot; tab.</li></ul><div class="warning custom-block"><p class="custom-block-title">Archiving Blocked</p><p>You cannot send a material to the archive if it is currently used in at least one active product template (in the Calculator) or if there is an uncompleted workbench job that requires it. The software will display a window listing the exact items blocking the archive operation. You will need to update those recipes first.</p></div>',31)])])}const m=t(r,[["render",s]]);export{d as __pageData,m as default};
